const fees = await fetch("https://ashtechpay.top/v1/fees", {
  headers: { "Authorization": "Bearer YOUR_API_KEY" }
}).then(r => r.json());

// Trouver les frais pour le pays du client
function getFeeForCountry(countryCode) {
  return fees.find(f => f.country_code === countryCode);
}

// Calculer le montant net crédité sur votre compte
function computeNet(grossAmount, countryCode) {
  const fee = getFeeForCountry(countryCode);
  if (!fee) return grossAmount;
  const feeAmount = Math.round(grossAmount * fee.total_fee_pct / 100);
  return {
    gross: grossAmount,
    fee: feeAmount,
    net: grossAmount - feeAmount,         // montant crédité sur votre wallet
    fee_pct: fee.total_fee_pct,
  };
}

// Exemple :
console.log(computeNet(10000, "CM"));
// → { gross: 10000, fee: 550, net: 9450, fee_pct: 5.5 }`})]})]}),e.jsxs("section",{id:"webhooks",ref:p=>c.current.webhooks=p,className:"scroll-mt-20 space-y-6",children:[e.jsxs("div",{className:"flex items-center gap-2 border-b border-gray-200 pb-4",children:[e.jsx(av,{className:"w-5 h-5 text-primary shrink-0"}),e.jsx("h2",{className:"text-xl font-semibold text-gray-900",children:"Webhooks"})]}),e.jsxs("p",{className:"text-gray-600 leading-relaxed",children:["Quand une transaction atteint un état final, Ashtech Pay envoie automatiquement une requête"," ",e.jsx("code",{className:"text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded text-xs",children:"POST"})," ","à la ",e.jsx("code",{className:"text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded text-xs",children:"notify_url"})," ","que vous avez passée dans votre appel à ",e.jsx("code",{className:"text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded text-xs",children:"/v1/collect"}),". Le champ ",e.jsx("code",{className:"text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded text-xs",children:"amount"})," correspond au montant net après frais, et ",e.jsx("code",{className:"text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded text-xs",children:"total_amount"})," au montant brut collecté."]}),e.jsxs("div",{className:"grid lg:grid-cols-2 gap-5",children:[e.jsxs("div",{className:"space-y-2 min-w-0",children:[e.jsx("p",{className:"text-xs font-semibold uppercase tracking-widest text-gray-500",children:"Payload — paiement réussi"}),e.jsx(or,{language:"json",code:`{
